SELECT DATE_TRUNC(created_at, MONTH) AS m, TIMESTAMP_TRUNC(created_at, DAY) AS d, DATE_ADD(DATE(created_at), INTERVAL 1 MONTH) AS e, DATE_DIFF(CURRENT_DATE(), DATE(created_at), DAY) AS f, EXTRACT(YEAR FROM created_at) AS y, EXTRACT(DAYOFWEEK FROM created_at) AS dow, FORMAT_TIMESTAMP('%Y-%m', created_at) AS ft, PARSE_TIMESTAMP('%Y', '2024') AS pt, TIMESTAMP_ADD(created_at, INTERVAL 1 HOUR) AS ta, TIMESTAMP_DIFF(CURRENT_TIMESTAMP(), created_at, SECOND) AS td, UNIX_SECONDS(created_at) AS us, TIMESTAMP_SECONDS(1) AS tsec, LAST_DAY(DATE(created_at), MONTH) AS ld, DATETIME(created_at, 'America/New_York') AS dtz, DATE(created_at, 'UTC') AS dz FROM `kumosql.kumosql_messy.raw_users`
